// Names of the Bengali letters and signs when said on their own (content/script/letter-names.json).
// next.config.ts turns the table into a compact map with buildLetterNames() and inlines it at build
// time (BL_LETTER_NAMES), like the audio manifest. Pure and safe to import anywhere.
//
// A letter played by itself uses the clip under "letter:<glyph>" (its name: ক → kɔ, ঙ → uŋɔ),
// generated by content/scripts/gen-audio.mjs. A one-letter word (ও "and") keeps its plain key.

export const LETTER_PREFIX = "letter:";

export interface LetterName {
  glyph: string;
  /** What to show under the glyph: the written name (তালব্য শ, ই-কার) or the glyph itself (ক). */
  label: string;
  /** Romanized name (content/TRANSLITERATION.md): "ko", "talobbo sho", "i-kar". */
  tr: string;
  /** Text a device voice speaks when there is no recorded letter clip. */
  say: string;
}

interface RawLetter {
  glyph?: unknown;
  kind?: unknown;
  name?: unknown;
  say?: unknown;
  tr?: unknown;
}

const nfc = (s: string) => s.normalize("NFC").trim();
const str = (v: unknown): string | undefined => (typeof v === "string" && v.trim() ? v : undefined);

/** Compact glyph → name map from the parsed letter-names.json; bad entries are skipped. */
export function buildLetterNames(doc: unknown): Record<string, LetterName> {
  const out: Record<string, LetterName> = {};
  const letters = (doc as { letters?: unknown } | null)?.letters;
  if (!Array.isArray(letters)) return out;
  for (const raw of letters as RawLetter[]) {
    const glyph = str(raw?.glyph);
    const tr = str(raw?.tr);
    if (!glyph || !tr) continue;
    const g = nfc(glyph);
    const name = str(raw.name);
    // Same default text as gen-audio's strategy d: the name, else the consonant with its vowel spelled out.
    const say = str(raw.say) ?? name ?? (raw.kind === "consonant" ? `${g}অ` : g);
    out[g] = { glyph: g, label: name ?? g, tr, say };
  }
  return out;
}

export function parseLetterNames(json: string | undefined): Record<string, LetterName> {
  try {
    const m = JSON.parse(json || "{}") as Record<string, LetterName>;
    return m && typeof m === "object" ? m : {};
  } catch {
    return {};
  }
}

const NAMES = parseLetterNames(process.env.BL_LETTER_NAMES);

/** The name of a letter or sign said on its own, or undefined if `bn` isn't one. */
export function letterName(bn: string): LetterName | undefined {
  const k = nfc(bn);
  return Object.prototype.hasOwnProperty.call(NAMES, k) ? NAMES[k] : undefined;
}

/** Manifest key of a letter's name clip (same as gen-audio.mjs). */
export const letterAudioKey = (glyph: string) => `${LETTER_PREFIX}${nfc(glyph)}`;
